if(!$p){http_response_code(404);$title='Artikel nicht gefunden';$effectivePrice=0;$saleActive=false;$newActive=false;$unitMeta=[];$features=[];}else{$title=trim((string)($p['seo_title']??''))!==''?(string)$p['seo_title']:(string)$p['name'];$saleActive=rh24_sale_is_active($p);$newActive=rh24_product_is_new_active($p);$effectivePrice=$saleActive?(float)($p['sale_price']??0):(float)$p['base_price'];$unitMeta=rh24_unit_price_meta($p,$effectivePrice);$features=rh24_json_decode((string)($p['features_json']??''),[]);}
$crossSell=[];$crossSellTitle='Passt perfekt dazu';if($p&&!empty($p['cross_sell_enabled'])){$crossSellTitle=trim((string)($p['cross_sell_title']??''))?:'Passt perfekt dazu';$max=max(1,min(8,(int)($p['cross_sell_max']??4)));$rels=rh24_cross_sell_clean(rh24_json_decode((string)($p['cross_sell_json']??''),[]),(string)$p['id']);$catalog=rh24_catalog();$seen=[];foreach($rels as $rel){$tid=(string)$rel['id'];$cp=$catalog[$tid]??null;if(!$cp||($cp['status']??'')!=='active'||empty($cp['shop_visible'])||($cp['type']??'')==='prototype')continue;$cp['cross_relation']=$rel['relation'];$cp['cross_note']=$rel['note'];$cp['cross_priority']=$rel['priority'];$crossSell[]=$cp;$seen[$tid]=true;if(count($crossSell)>=$max)break;}if(!empty($p['cross_sell_auto'])&&count($crossSell)<$max){$cur=strtolower((string)($p['category']??''));$tokens=str_contains($cur,'haken')?['lauge','mehl','gewürz','zubehör','thermo']:(str_contains($cur,'lauge')?['haken','mehl','gewürz']:(str_contains($cur,'mehl')?['haken','lauge','gewürz']:(str_contains($cur,'gewürz')?['haken','lauge','mehl','zubehör']:['zubehör','haken','lauge','mehl','gewürz'])));$rank=[];foreach($catalog as $tid=>$cp){if($tid===(string)$p['id']||isset($seen[$tid])||($cp['status']??'')!=='active'||empty($cp['shop_visible'])||($cp['type']??'')==='prototype')continue;$hay=strtolower((string)($cp['category']??'').' '.(string)($cp['name']??''));$score=!empty($cp['is_popular'])?6:0;$score+=!empty($cp['is_offer'])?2:0;foreach($tokens as $i=>$tok){if(str_contains($hay,$tok))$score+=10-$i;}if(strtolower((string)($cp['category']??''))===$cur)$score+=2;$rank[]=['p'=>$cp,'score'=>$score];}usort($rank,fn($a,$b)=>($b['score']<=>$a['score'])?:strcmp((string)$a['p']['name'],(string)$b['p']['name']));foreach($rank as $r){$cp=$r['p'];$cp['cross_relation']=strtolower((string)$cp['category'])===$cur?'alternative':'frequently_bought';$cp['cross_note']='';$crossSell[]=$cp;if(count($crossSell)>=$max)break;}}}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function rh24_plain_text($v){$t=html_entity_decode(strip_tags((string)$v),ENT_QUOTES,'UTF-8');$t=preg_replace('/\s+/u',' ',(string)$t);return trim((string)$t);}
function rh24_rich($v){
  $html=trim((string)$v);
  if($html==='')return '';
  if(strpos($html,'<')===false)return nl2br(h($html));
  $html=strip_tags($html,'<p><br><strong><b><em><i><u><s><strike><ul><ol><li><h3><h4><blockquote><hr><table><tbody><thead><tr><th><td><a>');
  $html=str_ireplace(['<b>','</b>','<i>','</i>','<strike>','</strike>'],['<strong>','</strong>','<em>','</em>','<s>','</s>'],$html);
  $html=preg_replace_callback("/<a\\b[^>]*href\\s*=\\s*([\"']?)([^\"'>\\s]+)\\1[^>]*>/i",function($m){
    $href=trim((string)($m[2]??''));
    if(!preg_match('/^(https?:|mailto:|tel:|\/|#)/i',$href))return '<a>';
    return '<a href="'.h($href).'" target="_blank" rel="noopener noreferrer">';
  },$html);
  $html=preg_replace('/<a(?![^>]*href=)[^>]*>/i','<a>',$html);
  $html=preg_replace_callback('/<(p|strong|em|u|s|ul|ol|li|h3|h4|blockquote|table|tbody|thead|tr|th|td)\b[^>]*>/i',fn($m)=>'<'.strtolower((string)$m[1]).'>',$html);
  $html=preg_replace('/<br\b[^>]*>/i','<br>',$html);
  $html=preg_replace('/<hr\b[^>]*>/i','<hr>',$html);
  $html=preg_replace('/<(?!\/?(?:p|br|strong|em|u|s|ul|ol|li|h3|h4|blockquote|hr|table|tbody|thead|tr|th|td|a)\b)[^>]*>/i','',$html);
  return $html;
}
